/// <summary>
/// Activates the botton "ShowUserCreatedOnly" by default
/// </summary>
/// <param name="sender">The sending form.</param>
/// <param name="e">The (unused) event arguments.</param>
[FormEventHandler(formStr(LedgerJournalTable), FormEventType::Initialized),
    SuppressBPWarning('BPParameterNotUsed', 'Parameter e not used')]
public static void Form_OnInitialized(xFormRun sender, FormEventArgs e)
{
    FormCheckBoxControl control = sender.design().controlName(formControlStr(LedgerJournalTable, ShowUserCreatedOnly));
    control.value(1);
}

/// <summary>
/// Jump ref for BEC_ledgerJournalRelatedToAllocation
/// </summary>
/// <param name="sender">BEC_ledgerJournalRelatedToAllocation</param>
/// <param name="e">The (unused) event arguments.</param>
[FormControlEventHandler(formControlStr(LedgerJournalTable, AVAledgerJournalRelatedToAllocation), FormControlEventType::JumpRef),
    SuppressBPWarning('BPParameterNotUsed', 'Parameter e not used')]
public static void BEC_ledgerJournalRelatedToAllocation_OnJumpRef(FormControl sender, FormControlEventArgs e)
{
    if (sender.valueStr() == strMin())
    {
        return;
    }

    Args args = new Args();
    //MenuFunction menuFunction = new MenuFunction(MenuItemDisplayStr(LedgerJournalTable3), MenuItemType::Display);
    MenuFunction  menuFunction = new MenuFunction(menuItemDisplayStr(ledgerjournaltable_allJournals), MenuItemType::Display);
    LedgerJournalTable ledgerJournalTable_loc = LedgerJournalTable::find(sender.valueStr());
    args.record(ledgerJournalTable_loc);
    args.caller(sender.formRun());

    menuFunction.run(args);
}

/// <summary>
/// AVA/WEN/2025/02/05   AVA_013036_ReverseJournal
/// </summary>
/// <param name = "sender">xFormRun</param>
/// <param name = "e">FormEventArgs</param>
[FormEventHandler(formStr(LedgerJournalTable), FormEventType::PostRun),
       SuppressBPWarning('BPParameterNotUsed', 'Parameter e not used')]
public static void LedgerJournalTable_OnPostRun(xFormRun sender, FormEventArgs e)
{
    FormStringControl   control = sender.design().controlName(formControlStr(LedgerJournalTable, LedgerJournalTable_AVAReversalJournalId));
    control.registerOverrideMethod(methodStr(FormStringControl, jumpRef), methodStr(AVALedgerJournalTableFrm_Extension, avaJumpRefReversalJournalId), sender);
}
